"guide-107-19":{t:"心理",tt:"服務",a:"答 <b class='ac'>C 消費者</b>。服務品質與價值最終決定者=消費者。",s:"品質價值決定者=消費者。"},
"guide-107-20":{t:"心理",tt:"馬斯洛",a:"答 <b class='ac'>C 歸屬感</b>。與家人親友情感聯繫=歸屬(社會)需求。",s:"親情聯繫=歸屬感。"},
"guide-107-21":{t:"心理",tt:"行銷",a:"答 <b class='ac'>C 旅遊市場</b>。現有+潛在購買者集合=市場。",s:"買者集合=市場。"},
"guide-107-22":{t:"心理",tt:"趨勢",a:"答 <b class='ac'>D 購買方式一成不變</b>(不影響)。旅客行為受人數成長、需求擴增、新產品影響。",s:"『一成不變』不影響趨勢。"},
"guide-107-23":{t:"心理",tt:"服務特性",a:"答 <b class='ac'>D 易滅性</b>。淡季促銷=克服易滅性(不可儲存)。",s:"淡季促銷=克服易滅性。"},
"guide-107-24":{t:"安全",tt:"火災",a:"答 <b class='ac'>B 唯一原則趕緊開門、向上逃</b>(錯誤)。開門前應<b class='wr'>試門把</b>,逃生方向視火勢。",s:"火災開門前試門把,非一律向上逃。"},
"guide-107-25":{t:"帶團",tt:"走失",a:"答 <b class='ac'>B 發動所有團員協尋</b>(非應有)。不應全員協尋而忽略其他人。",s:"走失勿全員協尋。"},
"guide-107-26":{t:"帶團",tt:"健康",a:"答 <b class='ac'>C 仍允許其參加水上活動</b>(不應)。發燒者不宜水上活動。",s:"發燒不參加水上活動。"},
"guide-107-27":{t:"帶團",tt:"操守",a:"答 <b class='ac'>C 私自與旅客兌換外幣</b>(不符)。領隊不得私兌外幣、收回扣。",s:"領隊不私兌外幣。"},
"guide-107-28":{t:"帶團",tt:"危機處理",a:"答 <b class='ac'>D 趁機讓旅客下車路邊舒展筋骨</b>(錯誤)。高速路旁危險,應留車內或安全處。",s:"爆胎勿讓旅客路邊逗留。"},
"guide-107-29":{t:"帶團",tt:"財物",a:"答 <b class='ac'>A 全部貴重財物放霹靂腰包集中保管</b>(最不當)。集中易一次全失,應分散。",s:"財物勿全集中一處。"},
"guide-107-30":{t:"帶團",tt:"財物",a:"答 <b class='ac'>D 全團行李託大廳清潔人員看管</b>(錯誤)。不可託不明人員。",s:"行李勿託清潔人員。"},
"guide-107-31":{t:"票務",tt:"機票",a:"答 <b class='ac'>D 直達航班</b>。Direct Flight=同班號直達(可中停不換機),行李直掛終點。",s:"Direct Flight=直達航班。"},
"guide-107-32":{t:"安全",tt:"危機處理",a:"答 <b class='ac'>A 要求壯碩男團員正面迎擊</b>(不應)。持刀行兇應迅速避離、報警,勿正面對抗。",s:"歹徒持刀勿迎擊,速避離報警。"},
"guide-107-33":{t:"帶團",tt:"英文",a:"答 <b class='ac'>A Do not disturb</b>(請勿打擾)。",s:"請勿打擾=Do not disturb。"},
"guide-107-34":{t:"票務",tt:"日期格式",a:"答 <b class='ac'>B 22FEB</b>。IATA 日期=日+月縮寫。",s:"IATA 日期=日+月(22FEB)。"},
"guide-107-35":{t:"票務",tt:"信用卡",a:"答 <b class='ac'>A AX</b>。AMERICAN EXPRESS=AX。",s:"AMEX=AX。"},
"guide-107-36":{t:"禮儀",tt:"拜訪",a:"答 <b class='ac'>D 於用膳時間拜訪</b>(不當)。拜訪應約時間、勿在用餐時段。",s:"勿於用膳時間拜訪。"},
"guide-107-37":{t:"禮儀",tt:"介紹禮儀",a:"答 <b class='ac'>D 國籍</b>(非考慮)。介紹序考慮地位、年齡、性別。",s:"介紹不看國籍。"},
"guide-107-38":{t:"禮儀",tt:"餐酒",a:"答 <b class='ac'>C 運送方式</b>(非考慮)。配酒看產地、年份、食物種類。",s:"配酒不看運送方式。"},
"guide-107-39":{t:"禮儀",tt:"宗教",a:"答 <b class='ac'>A 豬肉</b>(不可送回教徒)。伊斯蘭忌豬肉。",s:"回教徒忌豬肉。"},
"guide-107-40":{t:"禮儀",tt:"餐巾",a:"答 <b class='ac'>C 大略摺好放在桌上</b>。用畢餐巾略摺放桌左側。",s:"用畢餐巾略摺放桌上。"},
"guide-107-41":{t:"帶團",tt:"住宿",a:"答 <b class='ac'>A 逃生門</b>。住宿最應先檢查逃生門/逃生路線。",s:"住宿先看逃生門。"},
"guide-107-42":{t:"禮儀",tt:"乘車",a:"答 <b class='ac'>B 司機的右後方</b>。有司機時貴賓坐右後方(最尊)。",s:"有司機貴賓坐右後方。"},
